package com.example.com.englishai.backend.infrastructure.security;
import com.example.com.englishai.backend.domain.user.UserRole; import com.example.com.englishai.backend.infrastructure.persistence.repository.UserJpaRepository; import jakarta.servlet.*; import jakarta.servlet.http.*; import org.springframework.http.*; import org.springframework.security.core.context.SecurityContextHolder; import org.springframework.web.filter.OncePerRequestFilter; import java.io.IOException; import java.util.UUID;
public class AdminAuthorizationFilter extends OncePerRequestFilter { private final UserJpaRepository users; public AdminAuthorizationFilter(UserJpaRepository users){this.users=users;}
 protected void doFilterInternal(HttpServletRequest req,HttpServletResponse res,FilterChain chain)throws ServletException,IOException{if("OPTIONS".equalsIgnoreCase(req.getMethod())||!req.getRequestURI().startsWith("/api/v1/admin/")){chain.doFilter(req,res);return;}var auth=SecurityContextHolder.getContext().getAuthentication();if(auth==null||!(auth.getPrincipal() instanceof UUID id)){chain.doFilter(req,res);return;}var role=users.findById(id).map(u->u.getRole()).orElse(null);boolean usersManagement=req.getRequestURI().startsWith("/api/v1/admin/users");boolean allowed=role!=null&&role.atLeast(usersManagement?UserRole.SUPER_ADMIN:UserRole.ADMIN);if(!allowed){res.setStatus(HttpStatus.FORBIDDEN.value());res.setContentType(MediaType.APPLICATION_JSON_VALUE);res.getWriter().write("{\"message\":\"Forbidden\"}");return;}chain.doFilter(req,res);}
}
